with exploded as (select id, customer_id, coupon_codes, line.price, line.promo from carts lateral view outer explode(items) x as line) select case when price >= 239 then 'LARGE' else 'SMALL' end as price_tier, promo, sum(price) as total_price, percentile_approx(price, array(0.25, 0.5, 0.75)) as price_quartiles, count(*) filter (where promo = 'SPRING10') as spring10_rows, count_if(promo = 'WELCOME5') as welcome5_events from exploded group by rollup (case when price >= 239 then 'LARGE' else 'SMALL' end, promo) order by price_tier
